  // ==========================================================================
  // 9. WITHDRAW HOUSE FEES
  // ==========================================================================
  describe("Withdraw House Fees", () => {
    it("withdraws accumulated QP house fees", async () => {
      const houseAccount = await getAccount(
        provider.connection,
        qpPDAs.houseFeeUsdc,
      );
      const balance = Number(houseAccount.amount);

      if (balance > 0) {
        const destBefore = await getAccount(
          provider.connection,
          destinationUsdc,
        );

        await qpProgram.methods
          .withdrawHouseFees(new BN(balance))
          .accountsPartial({
            authority: authority.publicKey,
            lotteryState: mainPDAs.lotteryState,
            quickPickState: qpPDAs.quickPickState,
            houseFeeUsdc: qpPDAs.houseFeeUsdc,
            destinationUsdc,
            tokenProgram: TOKEN_PROGRAM_ID,
          })
          .rpc();

        const houseAfter = await getAccount(
          provider.connection,
          qpPDAs.houseFeeUsdc,
        );
        expect(Number(houseAfter.amount)).to.equal(0);

        const destAfter = await getAccount(
          provider.connection,
          destinationUsdc,
        );
        expect(Number(destAfter.amount) - Number(destBefore.amount)).to.equal(
          balance,
        );
      } else {
        // No accumulated fees — withdrawing with 0 funds must fail: the
        // handler clamps the amount to the available balance (0) and then
        // requires withdraw_amount > 0 (QuickPickError::InsufficientFunds).
        // Assert the expected failure so this test is never vacuous.
        try {
          await qpProgram.methods
            .withdrawHouseFees(new BN(1))
            .accountsPartial({
              authority: authority.publicKey,
              lotteryState: mainPDAs.lotteryState,
              quickPickState: qpPDAs.quickPickState,
              houseFeeUsdc: qpPDAs.houseFeeUsdc,
              destinationUsdc,
              tokenProgram: TOKEN_PROGRAM_ID,
            })
            .rpc();
          expect.fail("Should have thrown — no house fees to withdraw");
        } catch (err: unknown) {
          expect(err).to.exist;
          if (err instanceof AnchorError) {
            expect(err.error.errorCode.code).to.equal("InsufficientFunds");
          }
        }
      }
    });

    it("fails to withdraw from non-authority", async () => {
      try {
        await qpProgram.methods
          .withdrawHouseFees(new BN(1))
          .accountsPartial({
            authority: unauthorizedUser.publicKey,
            lotteryState: mainPDAs.lotteryState,
            quickPickState: qpPDAs.quickPickState,
            houseFeeUsdc: qpPDAs.houseFeeUsdc,
            destinationUsdc,
            tokenProgram: TOKEN_PROGRAM_ID,
          })
          .signers([unauthorizedUser])
          .rpc();
        expect.fail("Should have thrown — unauthorized");
      } catch (err: unknown) {
        expect(err).to.exist;
      }
    });
  });

