  // ==========================================================================
  // 12. EMERGENCY FUND TRANSFER
  // ==========================================================================
  describe("Emergency Fund Transfer", () => {
    it("fails when Quick Pick is not paused", async () => {
      const state = await qpProgramAccounts.quickPickState.fetch(
        qpPDAs.quickPickState,
      );
      expect(state.isPaused).to.be.false;

      try {
        await qpProgram.methods
          .emergencyFundTransfer(
            { reserve: {} },
            new BN(1_000_000),
            "Test emergency",
          )
          .accountsPartial({
            authority: authority.publicKey,
            lotteryState: mainPDAs.lotteryState,
            quickPickState: qpPDAs.quickPickState,
            sourceUsdc: qpPDAs.prizePoolUsdc,
            destinationUsdc,
            usdcMint,
            tokenProgram: TOKEN_PROGRAM_ID,
          })
          .rpc();
        expect.fail("Should have thrown — not paused");
      } catch (err: unknown) {
        expect(err).to.exist;
      }
    });

    it("transfers emergency funds when paused", async () => {
      await qpProgram.methods
        .pause("Emergency test")
        .accountsPartial({
          authority: authority.publicKey,
          lotteryState: mainPDAs.lotteryState,
          quickPickState: qpPDAs.quickPickState,
        })
        .rpc();

      const stateBefore = await qpProgramAccounts.quickPickState.fetch(
        qpPDAs.quickPickState,
      );
      const reserveBefore = stateBefore.reserveBalance.toNumber();

      if (reserveBefore > 0) {
        const transferAmt = new BN(Math.min(reserveBefore, 500_000_000)); // $500 or less

        // NOTE: the program restricts Reserve/Insurance emergency transfers
        // to protocol-PDA destinations (prize pool or insurance pool) —
        // see handler_emergency_fund_transfer in quickpick admin.rs. The
        // source here is the prize pool, so the destination must be the
        // insurance pool PDA (source == destination is also rejected).
        await qpProgram.methods
          .emergencyFundTransfer(
            { reserve: {} },
            transferAmt,
            "Reserve emergency",
          )
          .accountsPartial({
            authority: authority.publicKey,
            lotteryState: mainPDAs.lotteryState,
            quickPickState: qpPDAs.quickPickState,
            sourceUsdc: qpPDAs.prizePoolUsdc,
            destinationUsdc: qpPDAs.insurancePoolUsdc,
            usdcMint,
            tokenProgram: TOKEN_PROGRAM_ID,
          })
          .rpc();

        const stateAfter = await qpProgramAccounts.quickPickState.fetch(
          qpPDAs.quickPickState,
        );
        expect(stateAfter.reserveBalance.toNumber()).to.be.lessThan(
          reserveBefore,
        );
      } else {
        // No reserve funds — transferring with 0 reserve must fail with
        // QuickPickError::InsufficientFunds (reserve_balance >= amount).
        // Assert the expected failure so this test is never vacuous.
        try {
          await qpProgram.methods
            .emergencyFundTransfer(
              { reserve: {} },
              new BN(1),
              "Reserve emergency (expected failure)",
            )
            .accountsPartial({
              authority: authority.publicKey,
              lotteryState: mainPDAs.lotteryState,
              quickPickState: qpPDAs.quickPickState,
              sourceUsdc: qpPDAs.prizePoolUsdc,
              destinationUsdc: qpPDAs.insurancePoolUsdc,
              usdcMint,
              tokenProgram: TOKEN_PROGRAM_ID,
            })
            .rpc();
          expect.fail("Should have thrown — no reserve funds to transfer");
        } catch (err: unknown) {
          expect(err).to.exist;
          if (err instanceof AnchorError) {
            expect(err.error.errorCode.code).to.equal("InsufficientFunds");
          }
        }
      }

      // Unpause for further tests
      await qpProgram.methods
        .unpause()
        .accountsPartial({
          authority: authority.publicKey,
          lotteryState: mainPDAs.lotteryState,
          quickPickState: qpPDAs.quickPickState,
        })
        .rpc();
    });

    it("fails from non-authority", async () => {
      await qpProgram.methods
        .pause("Auth test")
        .accountsPartial({
          authority: authority.publicKey,
          lotteryState: mainPDAs.lotteryState,
          quickPickState: qpPDAs.quickPickState,
        })
        .rpc();

      try {
        await qpProgram.methods
          .emergencyFundTransfer({ reserve: {} }, new BN(1), "Unauthorized")
          .accountsPartial({
            authority: unauthorizedUser.publicKey,
            lotteryState: mainPDAs.lotteryState,
            quickPickState: qpPDAs.quickPickState,
            sourceUsdc: qpPDAs.prizePoolUsdc,
            destinationUsdc,
            usdcMint,
            tokenProgram: TOKEN_PROGRAM_ID,
          })
          .signers([unauthorizedUser])
          .rpc();
        expect.fail("Should have thrown — unauthorized");
      } catch (err: unknown) {
        expect(err).to.exist;
      }

      await qpProgram.methods
        .unpause()
        .accountsPartial({
          authority: authority.publicKey,
          lotteryState: mainPDAs.lotteryState,
          quickPickState: qpPDAs.quickPickState,
        })
        .rpc();
    });
  });

